import { webcrypto } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const resources = join(here, '..', 'app', 'src', 'test', 'resources');
mkdirSync(resources, { recursive: true });

const b64 = (bytes) => Buffer.from(bytes).toString('base64url');

const key = Uint8Array.from({ length: 32 }, (_, i) => i);
const wrongKey = Uint8Array.from({ length: 32 }, (_, i) => 255 - i);
const iv = Uint8Array.from({ length: 12 }, (_, i) => i);

const plaintexts = [
	{ name: 'ascii', plaintext: 'hello' },
	{ name: 'utf8', plaintext: 'héllo 🎉 世界' },
	{ name: 'yjs-like', plaintext: '\u0000\u0001binary-ish\u00ff' },
	{ name: 'empty', plaintext: '' }
];

const cryptoKey = await webcrypto.subtle.importKey('raw', key, { name: 'AES-GCM' }, false, ['encrypt']);

const cases = [];
for (const entry of plaintexts) {
	const plaintextBytes = new TextEncoder().encode(entry.plaintext);
	const sealed = new Uint8Array(
		await webcrypto.subtle.encrypt({ name: 'AES-GCM', iv }, cryptoKey, plaintextBytes)
	);
	const blob = new Uint8Array(iv.length + sealed.length);
	blob.set(iv, 0);
	blob.set(sealed, iv.length);
	cases.push({ name: entry.name, iv: b64(iv), plaintext: entry.plaintext, blob: b64(blob) });
}

const tampered = Uint8Array.from(Buffer.from(cases[0].blob, 'base64url'));
tampered[12] ^= 0x01;

const roomId = '11111111-1111-4111-8111-111111111111';
const editToken = '22222222-2222-4222-8222-222222222222';
const noteId = '33333333-3333-4333-8333-333333333333';
const keyEncoded = b64(key);
const base = 'https://notes.mdelacour.com';

const fixture = {
	comment:
		'Generated by apps/android/testdata/gen-crypto-fixtures.mjs; AES-256-GCM with 12-byte IV prefix, base64url unpadded.',
	key: keyEncoded,
	cases,
	wrongKey: b64(wrongKey),
	tampered: b64(tampered),
	links: [
		{ url: `${base}/s/${roomId}#${keyEncoded}`, roomId, key: keyEncoded, editToken: null, noteId: null },
		{
			url: `${base}/s/${roomId}#${keyEncoded}:${editToken}`,
			roomId,
			key: keyEncoded,
			editToken,
			noteId: null
		},
		{
			url: `${base}/s/${roomId}?n=${noteId}#${keyEncoded}`,
			roomId,
			key: keyEncoded,
			editToken: null,
			noteId
		}
	],
	rejected: [
		`${base}/n/${roomId}#${keyEncoded}`,
		`${base}/s/${roomId}`,
		`${base}/s/${roomId}#short`,
		'not a url',
		`${base}/s/not-a-uuid#${keyEncoded}`
	]
};

const output = join(resources, 'crypto-fixtures.json');
writeFileSync(output, `${JSON.stringify(fixture, null, 2)}\n`);
console.log(output);
